@props(['outcome', 'thresholdReached' => false])
<span @class(['inline-block rounded-full px-2.5 py-1 text-xs font-semibold', 'bg-red-100 text-red-800' => $outcome === 'Alert', 'bg-amber-100 text-amber-800' => in_array($outcome, ['Watch', 'Signal']), 'bg-green-100 text-green-800' => $outcome === 'Normal', 'bg-gray-100 text-gray-700' => $outcome === 'Insufficient Data'])>{{ match ($outcome) { 'Alert' => 'Unusual Increase Detected — Requires Review', 'Signal' => 'Below-Minimum Unusual Increase — Requires Review', 'Watch' => 'Watch', 'Normal' => $thresholdReached ? 'Threshold Reached' : 'Monitoring', 'Insufficient Data' => 'Not enough reliable data', default => $outcome } }}</span>
